/// Builds a CREATE TABLE plan.
fn build_create_table(&self, name: String, columns: Vec<ast::Column>) -> Result<Plan> {
    let mut schema_columns = Vec::new();
    let mut primary_key = None;
    for col in columns {
        if col.primary_key {
            primary_key = Some(schema_columns.len());
        }
        schema_columns.push(Column {
            name: col.name,
            datatype: col.datatype,
            nullable: col.nullable.unwrap_or(true),
            default: col.default.map(|e| Self::build_expression(e, &Scope::new())).transpose()?,
            unique: col.unique,
            index: col.index,
            references: col.references,
        });
    }
    let primary_key = primary_key.unwrap_or(0);
    let table = Table { name, primary_key, columns: schema_columns };
    Ok(Plan::CreateTable { schema: table })
}

